  .ot-month[data-variant="parenthesis"] .ot-month-day:is([data-between], [data-paren]) .ot-month-n { font-weight: 650; }
  .ot-month[data-variant="parenthesis"] .ot-month-day[data-when="today"] .ot-month-n { color: var(--ot-accent); font-weight: 700; }
  .ot-month[data-variant="parenthesis"] .ot-month-day[aria-selected="true"] .ot-month-n { color: var(--ot-ink); font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(1.1em * var(--ot-expression-scale)); }
  .ot-month[data-variant="parenthesis"] .ot-month-day[data-when="today"][aria-selected="true"] .ot-month-n { color: var(--ot-accent); }
  .ot-month[data-variant="parenthesis"] .ot-month-day::before,
  .ot-month[data-variant="parenthesis"] .ot-month-day::after { position: absolute; top: 50%; font-family: var(--ot-voice); font-style: normal; font-weight: 200; font-size: 1.3em; line-height: 1; color: var(--ot-pencil); opacity: 0; translate: 0 -54%; transition: opacity var(--ot-allegro); }
